104	export function tournamentWinner(
105	  playerSeeds: readonly [number, number],
106	  results: readonly [TournamentResult, TournamentResult],
107	): number {
108	  const [first, second] = results;
109	  if (first.moves !== second.moves)
110	    return first.moves < second.moves ? playerSeeds[0] : playerSeeds[1];
111	  if (first.elapsedMs !== second.elapsedMs)
112	    return first.elapsedMs < second.elapsedMs ? playerSeeds[0] : playerSeeds[1];
113	  return Math.min(playerSeeds[0], playerSeeds[1]);
114	}
