120	export function recordTournamentResult(
121	  tournament: Tournament,
122	  result: TournamentResult,
123	): Tournament {
124	  if (tournament.phase !== 'playing') return tournament;
125	  const match = tournament.matches[tournament.currentMatch];
126	  if (!match || match.results[tournament.currentTurn]) return tournament;
127	  const results: [TournamentResult | null, TournamentResult | null] = [...match.results];
128	  results[tournament.currentTurn] = result;
129	  let winnerSeed: number | null = null;
130	  let phase: TournamentPhase = 'next-turn';
131	  let championSeed = tournament.championSeed;
132	  if (tournament.currentTurn === 1) {
133	    const firstSeed = match.players[0];
134	    const secondSeed = match.players[1];
135	    const firstResult = results[0];
136	    const secondResult = results[1];
137	    if (firstSeed === null || secondSeed === null || !firstResult || !secondResult)
138	      return tournament;
139	    winnerSeed = tournamentWinner([firstSeed, secondSeed], [firstResult, secondResult]);
140	    if (tournament.currentMatch === tournament.matches.length - 1) {
141	      championSeed = winnerSeed;
142	      phase = 'complete';
143	    } else phase = 'next-match';
144	  }
145	  const matches = tournament.matches.map((item, index) =>
146	    index === tournament.currentMatch ? { ...item, results, winnerSeed } : item,
147	  );
148	  return { ...tournament, championSeed, matches, phase };
149	}
