157	export function nextTournamentMatch(tournament: Tournament): Tournament {
158	  if (tournament.phase !== 'next-match') return tournament;
159	  const nextIndex = tournament.currentMatch + 1;
160	  const next = tournament.matches[nextIndex];
161	  if (!next) return tournament;
162	  let players = next.players;
163	  const plan = roundPlan(tournament.players.length as 4 | 8);
164	  const nextRoundIndex = plan.findIndex((round) => round.name === next.round);
165	  if (nextRoundIndex < 0) return tournament;
166	  if (nextRoundIndex > 0) {
167	    const priorRoundStart = plan
168	      .slice(0, nextRoundIndex - 1)
169	      .reduce((sum, round) => sum + round.count, 0);
170	    const nextRoundStart = plan
171	      .slice(0, nextRoundIndex)
172	      .reduce((sum, round) => sum + round.count, 0);
173	    const withinRoundIndex = nextIndex - nextRoundStart;
174	    const sourceIndex = priorRoundStart + withinRoundIndex * 2;
175	    const sourceOne = tournament.matches[sourceIndex];
176	    const sourceTwo = tournament.matches[sourceIndex + 1];
177	    if (!sourceOne?.winnerSeed || !sourceTwo?.winnerSeed) return tournament;
178	    players = [sourceOne.winnerSeed, sourceTwo.winnerSeed];
179	  }
180	  const matches = tournament.matches.map((item, index) =>
181	    index === nextIndex ? { ...item, players } : item,
182	  );
183	  return { ...tournament, currentMatch: nextIndex, currentTurn: 0, matches, phase: 'ready' };
184	}
