199	    value.moves >= (size * size) / 2 &&
200	    value.moves <= MOVES_MAX &&
201	    Number.isFinite(value.elapsedMs) &&
202	    value.elapsedMs >= 0 &&
203	    value.elapsedMs <= ELAPSED_MAX_MS
204	  );
205	}
